    internal static IReadOnlyDictionary<string, string> BaseEnglishResources => English;

    private static readonly IReadOnlyList<LocalizedOption> Options =
    [
        new("auto", "Use Windows language"), new("en-US", "English"), new("zh-Hans", "简体中文"), new("zh-Hant", "繁體中文"), new("ja-JP", "日本語"), new("ko-KR", "한국어"), new("es-ES", "Español (España)"), new("fr-FR", "Français"), new("de-DE", "Deutsch"), new("pt-BR", "Português (Brasil)"), new("ru-RU", "Русский"), new("it-IT", "Italiano"), new("nl-NL", "Nederlands"), new("pl-PL", "Polski"), new("tr-TR", "Türkçe"), new("ar-SA", "العربية"),
        .. AdditionalLanguageResources.Languages
    ];

    private static IReadOnlyDictionary<string, string> _current = English;
    private static CultureInfo _currentCulture = CultureInfo.CurrentCulture;
    private static CultureInfo _currentUICulture = CultureInfo.CurrentUICulture;

    public static IReadOnlyList<LocalizedOption> LanguageOptions => Options
        .Select(option => option.Key == "auto"
            ? new LocalizedOption(option.Key, T("AutoLanguage"))
            : option)
        .ToArray();

    public static string CurrentLanguageCode { get; private set; } = "en-US";
    public static CultureInfo CurrentCulture => _currentCulture;
    public static CultureInfo CurrentUICulture => _currentUICulture;
    public static bool IsRightToLeft => _currentUICulture.TextInfo.IsRightToLeft;

    public static void SetLanguage(string? preference)
    {
        var normalizedPreference = NormalizePreference(preference);
        var useSystemLanguage = normalizedPreference == "auto";
        var code = useSystemLanguage
            ? ResolveSystemLanguage()
            : normalizedPreference;
        _current = GetDictionary(code);
        CurrentLanguageCode = code;
        _currentUICulture = ResolveFormattingCulture(code);
        _currentCulture = useSystemLanguage ? CultureInfo.CurrentCulture : _currentUICulture;
    }

    public static string T(string key, params object?[] args)
    {
        var value = LookUp(CurrentLanguageCode, _current, key);
        return args.Length == 0 ? value : string.Format(_currentCulture, value, args);
    }

    internal static string GetTextForLanguage(string languageCode, string key) =>
        LookUp(languageCode, GetDictionary(languageCode), key);

    private static IReadOnlyDictionary<string, string> GetDictionary(string code) =>
        LegacyLanguages.TryGetValue(code, out var dictionary) ? dictionary : AdditionalLanguageResources.Get(code);

    private static string LookUp(string code, IReadOnlyDictionary<string, string> dictionary, string key)
    {
        if (LocalizationResourceCatalog.TryGetLegacy(code, key, out var moduleText)) return moduleText;
        if (code == "zh-Hans" && SimplifiedChineseDocumentAdditions.TryGetValue(key, out var addition)) return addition;
        return dictionary.TryGetValue(key, out var value) ? value : English.GetValueOrDefault(key, key);
    }

    public static string ModeLabel(string key) => T(key switch { "fast" => "ModeFast", "balanced" => "ModeBalanced", "quality" => "ModeQuality", "lossless" => "ModeLossless", _ => "ModeBalanced" });

    public static string ResolveSystemLanguage()
    {
        return NormalizeCode(CultureInfo.CurrentUICulture.Name);
    }

    public static string NormalizePreference(string? preference) =>
        string.IsNullOrWhiteSpace(preference) || preference.Trim().Equals("auto", StringComparison.OrdinalIgnoreCase)
            ? "auto"
            : NormalizeCode(preference);

    public static string NormalizeCode(string code)
    {
        if (string.IsNullOrWhiteSpace(code))
        {
            return "en-US";
        }

        var normalized = code.Trim().Replace('_', '-');
        var exact = LocalizedResourceModule.SupportedLanguageCodes.FirstOrDefault(language => language.Equals(normalized, StringComparison.OrdinalIgnoreCase));
        if (exact is not null)
        {
            return exact;
        }

        var subtags = normalized.Split('-');
        var language = subtags[0].ToLowerInvariant();
        var second = subtags.Length > 1 ? subtags[1].ToLowerInvariant() : "";
        var region = second.Length == 4 && subtags.Length > 2 ? subtags[2].ToLowerInvariant() : second;
        if (language == "es")
        {
            return region switch
            {
                "019" or "419" or "ar" or "bo" or "br" or "bz" or "ca" or "cl" or "co" or "cr" or "cu"
                    or "do" or "ec" or "gt" or "hn" or "mx" or "ni" or "pa" or "pe" or "pr" or "py"
                    or "sv" or "us" or "uy" or "ve" => "es-419",
                _ => "es-ES"
            };
        }
        if (language == "zh")
        {
            if (second == "yue") return "yue-Hant-HK";
            if (second is "hans" or "chs") return "zh-Hans";
            return second is "hant" or "cht" || region is "tw" or "hk" or "mo" ? "zh-Hant" : "zh-Hans";
        }
        if (language == "pnb") return "pa-Arab-PK";
        if (language == "pa") return second == "arab" || (second != "guru" && region == "pk") ? "pa-Arab-PK" : "pa-IN";
        if (language == "sr") return second == "cyrl" ? "sr-Cyrl-RS" : "sr-Latn-RS";
        if (language == "no") return "nb-NO";
        if (language == "pt") return region == "br" ? "pt-BR" : "pt-PT";
        var additional = AdditionalLanguageResources.Languages.FirstOrDefault(option =>
            option.Key.StartsWith(language + "-", StringComparison.OrdinalIgnoreCase));
        if (additional is not null) return additional.Key;
        return language switch
        {
            "en" => "en-US",
            "ja" => "ja-JP",
            "ko" => "ko-KR",
            "fr" => "fr-FR",
            "de" => "de-DE",
            "ru" => "ru-RU",
            "it" => "it-IT",
            "nl" => "nl-NL",
            "pl" => "pl-PL",
            "tr" => "tr-TR",
            "ar" => "ar-SA",
            _ => "en-US"
        };
    }

    private static CultureInfo ResolveFormattingCulture(string code) => CultureInfo.GetCultureInfo(code switch
    {
        "zh-Hans" => "zh-CN",
        "zh-Hant" => "zh-TW",
        _ => code
    });

    private static IReadOnlyDictionary<string, string> Create(Dictionary<string, string> overrides)
    {
        var result = new Dictionary<string, string>(English, StringComparer.Ordinal);
        foreach (var pair in overrides)
        {
            result[pair.Key] = pair.Value;
        }
        return result;
    }
}
